    /**
     * @method
     * @name mercado#fetchMarkets
     * @description retrieves data on all markets for mercado
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object[]} an array of objects representing market data
     */
    public CompletableFuture<Object> fetchMarkets(Map<String, Object> parameters)
    {

        return BaseExchange.supplyAsync(() -> {

            List<Object> response = (this.publicGetCoins(parameters)).join();
            //
            //     [
            //         "BCH",
            //         "BTC",
            //         "ETH",
            //         "LTC",
            //         "XRP",
            //         "MBPRK01",
            //         "MBPRK02",
            //         "MBPRK03",
            //         "MBPRK04",
            //         "MBCONS01",
            //         "USDC",
            //         "WBX",
            //         "CHZ",
            //         "MBCONS02",
            //         "PAXG",
            //         "MBVASCO01",
            //         "LINK"
            //     ]
            //
            List<Object> result = new ArrayList<Object>(Arrays.asList());
            Map<String, Object> amountLimits = (Map<String, Object>) this.safeDict(this.options, "limits", new HashMap<String, Object>() {{}});
            List<Object> coins = this.toArray(response);
            for (var i = 0; i < ((List<?>)coins).size(); i++)
            {
                Object coin = (coins == null || i < 0 || i >= coins.size() ? null : coins.get(i));
                Object baseId = coin;
                String quoteId = "BRL";
                String base = this.safeCurrencyCode((String) (baseId), (Map<String, Object>) null);
                String quote = this.safeCurrencyCode(quoteId, (Map<String, Object>) null);
                if ((java.util.Objects.equals(base, null)) || (java.util.Objects.equals(quote, null)))
                {
                    continue;
                }
                String id = (quote + base);
                ((List<Object>)result).add(Helpers.newMap(
                    "id", id,
                    "symbol", ((base + "/") + quote),
                    "base", base,
                    "quote", quote,
                    "settle", null,
                    "baseId", baseId,
                    "quoteId", quoteId,
                    "settleId", null,
                    "type", "spot",
                    "spot", true,
                    "margin", false,
                    "swap", false,
                    "future", false,
                    "option", false,
                    "active", null,
                    "contract", false,
                    "linear", null,
                    "inverse", null,
                    "contractSize", null,
                    "expiry", null,
                    "expiryDatetime", null,
                    "strike", null,
                    "optionType", null,
                    "precision", new HashMap<String, Object>() {{
                        put( "amount", Mercado.this.parseNumber("1e-8") );
                        put( "price", Mercado.this.parseNumber("1e-5") );
                    }},
                    "limits", new HashMap<String, Object>() {{
                        put( "leverage", new HashMap<String, Object>() {{
                            put( "min", null );
                            put( "max", null );
                        }} );
                        put( "amount", new HashMap<String, Object>() {{
                            put( "min", Mercado.this.safeNumber(amountLimits, baseId, (Object) null) );
                            put( "max", null );
                        }} );
                        put( "price", new HashMap<String, Object>() {{
                            put( "min", Mercado.this.parseNumber("1e-5") );
                            put( "max", null );
                        }} );
                        put( "cost", new HashMap<String, Object>() {{
                            put( "min", null );
                            put( "max", null );
                        }} );
                    }},
                    "created", null,
                    "info", coin
                ));
            }
            return result;
        });

    }

    /**
     * @method
     * @name mercado#fetchOrderBook
     * @description fetches information on open orders with bid (buy) and ask (sell) prices, volumes and other data
     * @param {string} symbol unified symbol of the market to fetch the order book for
     * @param {int} [limit] the maximum amount of order book entries to return
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} an [order book structure]{@link https://docs.ccxt.com/?id=order-book-structure}
     */
    public CompletableFuture<OrderBook> fetchOrderBook(Object symbol, Long limit, Map<String, Object> parameters)
    {

        return BaseExchange.supplyAsync(() -> {

            if (java.util.Objects.equals(this.markets, null))
            {
                (this.loadMarkets(false, new HashMap<String, Object>() {{}})).join();
            }
            Map<String, Object> market = (Map<String, Object>) this.market(symbol);
            Map<String, Object> request = new HashMap<String, Object>() {{
                put( "coin", ((Map<String, Object>)market).get("base") );
            }};
            Map<String, Object> response = (this.publicGetCoinOrderbook(this.extend(request, parameters))).join();
            return this.parseOrderBook(response, ((Map<String, Object>)market).get("symbol"), (Long) null, "bids", "asks", 0, 1, 2);
        }).thenApply(OrderBook::new);

    }

    public Object parseTicker(Object ticker, Map<String, Object> market)
    {
        //
        //     {
        //         "high":"103.96000000",
        //         "low":"95.00000000",
        //         "vol":"2227.67806598",
        //         "last":"97.91591000",
        //         "buy":"95.52760000",
        //         "sell":"97.91475000",
        //         "open":"99.79955000",
        //         "date":1643382606
        //     }
        //
        String symbol = this.safeSymbol(null, market, (String) null, (String) null);
        Long timestamp = this.safeTimestamp(ticker, "date");
        String last = this.safeString(ticker, "last");
        return this.safeTicker(new HashMap<String, Object>() {{
            put( "symbol", symbol );
            put( "timestamp", timestamp );
            put( "datetime", Mercado.this.iso8601(timestamp) );
            put( "high", Mercado.this.safeString(ticker, "high") );
            put( "low", Mercado.this.safeString(ticker, "low") );
            put( "bid", Mercado.this.safeString(ticker, "buy") );
            put( "bidVolume", null );
            put( "ask", Mercado.this.safeString(ticker, "sell") );
            put( "askVolume", null );
            put( "vwap", null );
            put( "open", null );
            put( "close", last );
            put( "last", last );
            put( "previousClose", null );
            put( "change", null );
            put( "percentage", null );
            put( "average", null );
            put( "baseVolume", Mercado.this.safeString(ticker, "vol") );
            put( "quoteVolume", null );
            put( "info", ticker );
        }}, market);
    }

