    public Object parseOrder(Object order, Map<String, Object> market)
    {
        //
        //     {
        //         "order_id": 4,
        //         "coin_pair": "BRLBTC",
        //         "order_type": 1,
        //         "status": 2,
        //         "has_fills": true,
        //         "quantity": "2.00000000",
        //         "limit_price": "900.00000",
        //         "executed_quantity": "1.00000000",
        //         "executed_price_avg": "900.00000",
        //         "fee": "0.00300000",
        //         "created_timestamp": "1453838494",
        //         "updated_timestamp": "1453838494",
        //         "operations": [
        //             {
        //                 "operation_id": 1,
        //                 "quantity": "1.00000000",
        //                 "price": "900.00000",
        //                 "fee_rate": "0.30",
        //                 "executed_timestamp": "1453838494",
        //             },
        //         ],
        //     }
        //
        String id = this.safeString(order, "order_id");
        String order_type = this.safeString(order, "order_type");
        String side = null;
        if (((Map<?, ?>)order).containsKey("order_type"))
        {
            side = (((java.util.Objects.equals(order_type, "1")))) ? "buy" : "sell";
        }
        String status = this.parseOrderStatus(this.safeString(order, "status"));
        String marketId = this.safeString(order, "coin_pair");
        Map<String, Object> marketResolved = (Map<String, Object>) this.safeMarket(marketId, market, (String) null, (String) null);
        Long timestamp = this.safeTimestamp(order, "created_timestamp");
        Map<String, Object> fee = new HashMap<String, Object>() {{
            put( "cost", Mercado.this.safeString(order, "fee") );
            put( "currency", ((Map<String, Object>)marketResolved).get("quote") );
        }};
        String price = this.safeString(order, "limit_price");
        // price = this.safeNumber (order, 'executed_price_avg', price);
        String average = this.safeString(order, "executed_price_avg");
        String amount = this.safeString(order, "quantity");
        String filled = this.safeString(order, "executed_quantity");
        Long lastTradeTimestamp = this.safeTimestamp(order, "updated_timestamp");
        List<Object> rawTrades = (List<Object>) this.safeList(order, "operations", new ArrayList<Object>(Arrays.asList()));
        String symbol = (String) ((Map<String, Object>)marketResolved).get("symbol");
        return this.safeOrder(Helpers.newMap(
            "info", order,
            "id", id,
            "clientOrderId", null,
            "timestamp", timestamp,
            "datetime", this.iso8601(timestamp),
            "lastTradeTimestamp", lastTradeTimestamp,
            "symbol", symbol,
            "type", "limit",
            "timeInForce", null,
            "postOnly", null,
            "side", side,
            "price", price,
            "triggerPrice", null,
            "cost", null,
            "average", average,
            "amount", amount,
            "filled", filled,
            "remaining", null,
            "status", status,
            "fee", fee,
            "trades", rawTrades
        ), Helpers.toMapArg(marketResolved));
    }

